import {sectionSpacing,repeatPattern} from './pattern.js';
import {icon} from './icons.js';
export function patternUI({getModel,getIds,commit,toast}){
 const panel=document.createElement('div');panel.className='pattern-panel';panel.hidden=true;document.querySelector('.stage').append(panel);let ids=[],steps=[];
 panel.innerHTML=`<div class="motor-panel-title"><strong>Repeat section</strong><button aria-label="Close repeat panel" id="pattern-close">×</button></div><p id="pattern-summary"></p><label class="field"><span>World direction</span><select aria-label="Repeat direction" id="pattern-direction">${['+X','−X','+Y','−Y','+Z','−Z'].map((a,i)=>`<option value="${i}">${a}</option>`).join('')}</select></label><label class="field"><span>Spacing</span><select id="pattern-fit" aria-label="Pattern spacing mode"><option value="fit">Fit selected section</option><option value="custom">Custom spacing</option></select></label><label class="field"><span>Step · mm</span><input id="pattern-spacing" aria-label="Pattern spacing in millimeters" type="number" min="0.1" max="10000" step="0.1" value="75" disabled></label><button class="pattern-plus" id="pattern-add" aria-label="Add one repeat">${icon('add')} Extend one section</button><p class="note">Shared parts are reused. Occupied positions are skipped, leaving existing parts untouched. Each click advances one full section.</p><p id="pattern-result" role="status"></p>`;
 const $=s=>panel.querySelector(s),direction=()=>{const i=Number($('#pattern-direction').value),v=[0,0,0];v[Math.floor(i/2)]=i%2?-1:1;return v;};
 function spacing(){const auto=$('#pattern-fit').value==='fit';$('#pattern-spacing').disabled=auto;if(auto)$('#pattern-spacing').value=Number(sectionSpacing(getModel(),ids,direction()).toFixed(6));}
 function open(){ids=[...getIds()];if(!ids.length){toast('Select a part or Shift-click the section to repeat.');return;}steps=[];$('#pattern-fit').value='fit';spacing();$('#pattern-result').textContent='';const size=[0,1,2].map(i=>sectionSpacing(getModel(),ids,[0,1,2].map(j=>i===j?1:0)).toFixed(1));$('#pattern-summary').textContent=`${ids.length} parts · X ${size[0]} / Y ${size[1]} / Z ${size[2]} mm`;panel.hidden=false;$('#pattern-add').focus();}
 $('#pattern-close').onclick=()=>panel.hidden=true;$('#pattern-direction').onchange=()=>{steps=[];spacing();$('#pattern-result').textContent='Direction changed. Extending from the original section.';};$('#pattern-fit').onchange=()=>{steps=[];spacing();};$('#pattern-spacing').onchange=()=>steps=[];
 $('#pattern-add').onclick=()=>{try{const m=getModel(),valid=new Set(m.parts.map(p=>p.id));if(!ids.every(id=>valid.has(id)))throw Error('The section changed. Close this panel and select a new section.');const undone=steps.findIndex(s=>s.added.some(id=>!valid.has(id)));if(undone>=0)steps=steps.slice(0,undone);spacing();const step=Number($('#pattern-spacing').value);if(!Number.isFinite(step)||step<=0||step>10000)throw Error('Use a spacing above 0 and at most 10000 mm.');const result=repeatPattern(m,{ids,copies:1,delta:direction().map(v=>v*step*(steps.length+1))}),last=result.steps[0];if(result.stats.added||result.stats.links)commit(result.model,last.ids);steps.push(last);$('#pattern-result').textContent=`Step ${steps.length}: ${result.stats.added} added · ${result.stats.reused} shared · ${result.stats.skipped} blocked. ${result.stats.added?'Undo restores this step.':'Click + to continue beyond this position.'}`;}catch(e){$('#pattern-result').textContent=e.message;}};
 return{open,close(){panel.hidden=true;}};
}
